import { RULES_BY_ID } from "./rules";
import type { ModelReview } from "./schema";
import type {
  Confidence,
  DimensionScore,
  ReviewDimension,
  ReviewFinding,
  ReviewInput,
  ReviewResult,
  ReviewStatus,
  ReviewVerdict,
} from "./types";

type LocalMatch = {
  ruleId: string;
  pattern: RegExp;
  whatIsOff: string;
  whyItMatters: string;
  replacement?: string;
  confidence?: Confidence;
};

const LOCAL_MATCHES: LocalMatch[] = [
  { ruleId: "P04", pattern: /\b(erase[sd]?|eliminate[sd]?|cures?|guarantee[sd]?|permanent(?:ly)?|100\s*%|zero side effects?)\b/i, whatIsOff: "This is an absolute or guaranteed outcome.", whyItMatters: "A qualification cannot reliably correct an unconditional main promise.", replacement: "Helps target the visible concern with consistent use." },
  { ruleId: "P05", pattern: /\b(treats?|heals?|reverses?|kills? bacteria|eczema|psoriasis|dermatitis|melasma|wound(?:s| healing)?)\b/i, whatIsOff: "This may read as a disease-treatment or physiological claim.", whyItMatters: "The wording may exceed the product's approved cosmetic classification.", replacement: "Supports the appearance and comfort of concern-prone skin." },
  { ruleId: "P03", pattern: /\b(dermatologist|doctor|expert|pediatrician|paediatrician)[- ]?(approved|recommended|tested|backed)?\b/i, whatIsOff: "An expert or authority endorsement is being used.", whyItMatters: "The endorsement needs a matching source, scope, permission, and date." },
  { ruleId: "P02", pattern: /(?:\b(?:up to\s+)?\d+(?:\.\d+)?\s*%\s+(?:reduction|less|more|of|subjects?|users?|agree|improvement)|\b(?:reduces?|improves?|increases?)\b[^.\n]{0,45}\b\d+(?:\.\d+)?\s*%|\b(?:in|within|after)\s+\d+\s*(?:hours?|days?|weeks?|months?)\b|\bclinically\s+(?:proven|tested)\b|\b\d+x\s+(?:faster|more|better|stronger)\b)/i, whatIsOff: "This is a numeric, time-bound, clinical, or measurable efficacy claim.", whyItMatters: "The exact wording and conditions must match approved substantiation." },
  { ruleId: "P06", pattern: /\b(before\s*(?:&|and|\/)\s*after|real results?|customer review|testimonial)\b/i, whatIsOff: "The ad presents a result comparison or testimonial.", whyItMatters: "Permission, typicality, timeframe, alterations, and matching product use must be verified." },
  { ruleId: "P08", pattern: /\b(free|cashback|\d+\s*%\s*off|limited[- ]time|buy\s+\d+\s+get\s+\d+)\b/i, whatIsOff: "The promotion may be missing material conditions.", whyItMatters: "Customers need the threshold, validity, exclusions, and redemption route before acting." },
  { ruleId: "T01", pattern: /\b(ugly|disgusting|embarrassing|unacceptable|gross)\b/i, whatIsOff: "The concern is framed in shaming language.", whyItMatters: "Minimalist's tone should inform without judging the customer." },
  { ruleId: "T02", pattern: /\b(dangerous|toxic|scary|warning!|act now before|don't let .* ruin)\b/i, whatIsOff: "The copy uses fear or disproportionate urgency.", whyItMatters: "Fear-based pressure works against an evidence-led, informed choice." },
  { ruleId: "T03", pattern: /(?:!{2,}|[🔥🚨😱]{2,}|\b(miracle|life[- ]changing|magical transformation)\b)/iu, whatIsOff: "The execution relies on hype or pressure.", whyItMatters: "The brand standard calls for calm, specific confidence.", replacement: "State one concrete, supportable product benefit." },
  { ruleId: "T04", pattern: /\b(erase[sd]?|eliminate[sd]?|cures?|guarantee[sd]?|instant(?:ly)?|permanent(?:ly)?|100\s*%)\b/i, whatIsOff: "The tone implies a certain, universal or instant result.", whyItMatters: "Minimalist communicates transparent expectations rather than inevitable transformation." },
  { ruleId: "L02", pattern: /\b(erase[sd]?|eliminate[sd]?|cures?|guarantee[sd]?|instant(?:ly)?|permanent(?:ly)?|100\s*%)\b/i, whatIsOff: "The efficacy verb is stronger than an evidence-matched cosmetic benefit claim.", whyItMatters: "Minimalist's claim language calibrates benefit verbs to the approved evidence.", replacement: "Helps target the visible concern with consistent use." },
  { ruleId: "L05", pattern: /\b(glow[- ]?up|maximum results?|powerful solution|flawless skin|unlock your beauty)\b/i, whatIsOff: "Generic beauty filler replaces useful product information.", whyItMatters: "Specific product facts are clearer and more credible." },
  { ruleId: "L07", pattern: /\b(buy now or regret|fix your skin now|get flawless now|don't miss your transformation)\b/i, whatIsOff: "The CTA adds pressure or promises a result.", whyItMatters: "A CTA changes the overall claim and should remain factual." },
];

const STATUS_ORDER: Record<ReviewStatus, number> = {
  pass: 0,
  revise: 1,
  evidence_required: 2,
  human_review: 3,
  block: 4,
};

function findingFromMatch(match: LocalMatch, textMatch: RegExpMatchArray, index: number): ReviewFinding {
  const rule = RULES_BY_ID.get(match.ruleId)!;
  return {
    id: `local-${rule.id}-${index}`,
    ruleId: rule.id,
    ruleName: rule.name,
    dimension: rule.dimension,
    status: rule.status,
    severity: rule.severity,
    location: "Visible or supplied ad copy",
    observed: textMatch[0],
    inference: null,
    whatIsOff: match.whatIsOff,
    whyItMatters: match.whyItMatters,
    howToFix: rule.action,
    suggestedReplacement: match.replacement ?? null,
    doneWhen: "The flagged wording is removed or replaced, and any required evidence or specialist approval is attached.",
    confidence: match.confidence ?? "high",
    missingInput: rule.status === "evidence_required" ? "Approved claim wording and substantiation record" : null,
    sourceBasis: rule.sourceBasis,
  };
}

export function analyzeText(input: ReviewInput): ReviewFinding[] {
  const text = [input.knownText, input.postCopy].filter(Boolean).join("\n").trim();
  if (!text) return [];

  const findings = LOCAL_MATCHES.flatMap((matcher, index) => {
    const match = text.match(matcher.pattern);
    return match ? [findingFromMatch(matcher, match, index)] : [];
  });

  if (input.productContext?.url && input.source === "generator") {
    const rule = RULES_BY_ID.get("P11")!;
    findings.push({
      id: "local-P11-product-page",
      ruleId: rule.id,
      ruleName: rule.name,
      dimension: rule.dimension,
      status: rule.status,
      severity: rule.severity,
      location: "Product-page-derived ad copy",
      observed: text.slice(0, 180),
      inference: "The generator used a public product page, but this prototype has no internal approved-claims registry.",
      whatIsOff: "Publication on a product page does not prove approval for this ad wording and channel.",
      whyItMatters: "Shortening or recombining copy can remove the population, timeframe, method, or qualification.",
      howToFix: rule.action,
      suggestedReplacement: null,
      doneWhen: "Each factual benefit line is linked to an approved ad-channel claim record with the same scope and qualifiers.",
      confidence: "high",
      missingInput: "Internal approved-claims registry and substantiation mapping",
      sourceBasis: rule.sourceBasis,
    });
  }

  return findings;
}

function normalizeModelFindings(model: ModelReview): ReviewFinding[] {
  return model.findings.flatMap((finding, index) => {
    const rule = RULES_BY_ID.get(finding.ruleId.toUpperCase());
    if (!rule) return [];
    return [{
      id: `vision-${rule.id}-${index}`,
      ruleId: rule.id,
      ruleName: rule.name,
      dimension: rule.dimension,
      status: rule.status,
      severity: rule.severity,
      location: finding.location,
      observed: finding.observed,
      inference: finding.inference,
      whatIsOff: finding.whatIsOff,
      whyItMatters: finding.whyItMatters,
      howToFix: finding.howToFix || rule.action,
      suggestedReplacement: finding.suggestedReplacement,
      doneWhen: finding.doneWhen,
      confidence: finding.confidence,
      missingInput: finding.missingInput,
      sourceBasis: rule.sourceBasis,
    }];
  });
}

function dedupeFindings(findings: ReviewFinding[]) {
  const seen = new Set<string>();
  return findings.filter((finding) => {
    const key = `${finding.ruleId}:${finding.observed.trim().toLowerCase()}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function strongestStatus(statuses: ReviewStatus[]): ReviewStatus {
  return statuses.reduce<ReviewStatus>((strongest, status) =>
    STATUS_ORDER[status] > STATUS_ORDER[strongest] ? status : strongest, "pass");
}

function verdictFor(status: ReviewStatus): ReviewVerdict {
  if (status === "block") return "do_not_publish";
  if (status === "human_review") return "human_review";
  if (status === "evidence_required") return "evidence_required";
  if (status === "revise") return "revise";
  return "ready_for_reviewer_approval";
}

const VERDICT_SUMMARIES: Record<ReviewVerdict, string> = {
  do_not_publish: "Do not publish yet. Resolve the critical finding first.",
  human_review: "A specialist decision or missing visual review is required before publication.",
  evidence_required: "The creative needs claim evidence or an approved claim match before publication.",
  revise: "Revise the flagged copy or execution, then score the updated creative again.",
  ready_for_reviewer_approval: "No issue was detected by this prototype. It is ready for final reviewer approval—not automatically approved.",
};

const PASS_COPY: Record<ReviewDimension, Pick<DimensionScore, "explanation" | "action">> = {
  policy: {
    explanation: "No unsubstantiated, non-compliant or legally risky claim was detected.",
    action: "No change needed. Keep every factual claim matched to approved evidence.",
  },
  tone: {
    explanation: "The ad is calm, respectful and informative rather than generic or pressuring.",
    action: "No change needed. Keep the tone specific, calm and customer-respectful.",
  },
  language: {
    explanation: "Product naming, benefit wording and claim structure match the documented brand pattern.",
    action: "No change needed. Keep product and ingredient wording precise and supportable.",
  },
};

function scoreForFindings(findings: ReviewFinding[]): DimensionScore["score"] {
  if (!findings.length) return 5;
  if (findings.some((finding) => finding.status === "block")) return 1;
  if (findings.some((finding) => finding.status === "human_review")) return 2;

  const serious = findings.filter(
    (finding) => finding.status === "evidence_required" || finding.severity === "high" || finding.severity === "critical",
  );
  if (serious.length > 1) return 2;
  if (serious.length === 1 || findings.length > 1) return 3;
  return 4;
}

function trimSentence(value: string, maxLength = 220) {
  if (value.length <= maxLength) return value;
  return `${value.slice(0, maxLength - 1).trimEnd()}…`;
}

function buildDimensionScore(
  dimension: ReviewDimension,
  findings: ReviewFinding[],
): DimensionScore {
  if (!findings.length) {
    return { score: 5, ...PASS_COPY[dimension], ruleIds: [] };
  }

  const ordered = [...findings].sort((left, right) => {
    const statusDifference = STATUS_ORDER[right.status] - STATUS_ORDER[left.status];
    if (statusDifference) return statusDifference;
    const severityOrder = { low: 0, medium: 1, high: 2, critical: 3 };
    return severityOrder[right.severity] - severityOrder[left.severity];
  });
  const explanation = ordered
    .slice(0, 2)
    .map((finding) => finding.whatIsOff)
    .filter((value, index, values) => values.indexOf(value) === index)
    .join(" ");
  const actions = ordered
    .slice(0, 2)
    .map((finding) => finding.suggestedReplacement
      ? `Replace “${finding.observed}” with “${finding.suggestedReplacement}”`
      : finding.howToFix)
    .filter((value, index, values) => values.indexOf(value) === index);
  const actionLine = actions
    .map((action, index) => index === 0 ? action : `${action.charAt(0).toLowerCase()}${action.slice(1)}`)
    .join(" Then ");

  return {
    score: scoreForFindings(findings),
    explanation: trimSentence(explanation),
    action: trimSentence(actionLine, 280),
    ruleIds: [...new Set(findings.map((finding) => finding.ruleId))],
  };
}

export function assembleReview(
  input: ReviewInput,
  model: ModelReview | null,
  modelError?: string,
): ReviewResult {
  const local = analyzeText(input);
  const vision = model ? normalizeModelFindings(model) : [];
  const limitations: string[] = [];
  let findings = dedupeFindings([...local, ...vision]);

  if (!model && input.imageDataUrl) {
    findings.push({
      id: "input-visual-review",
      ruleId: "INPUT",
      ruleName: "Visual review unavailable",
      dimension: "policy",
      status: "human_review",
      severity: "high",
      location: "Uploaded creative",
      observed: "The image was received, but no vision model was available to read it.",
      inference: null,
      whatIsOff: "Visual copy, disclaimer legibility, layout, and asset integrity have not been assessed.",
      whyItMatters: "A text-only check cannot safely clear an image ad.",
      howToFix: "Configure GEMINI_API_KEY and rescore, or paste all visible copy and complete a manual visual review.",
      suggestedReplacement: null,
      doneWhen: "The image has been read by the vision scorer or signed off by a human reviewer.",
      confidence: "high",
      missingInput: "Vision analysis",
      sourceBasis: "Scorer input-quality safeguard",
    });
    limitations.push(modelError ?? "Gemini vision is not configured; only supplied text was checked.");
  }

  if (!input.imageDataUrl) {
    limitations.push("No ad image was supplied; visual hierarchy, disclaimer legibility, and asset integrity were not assessed.");
  }

  const dimensions = (["policy", "tone", "language"] as ReviewDimension[]).reduce(
    (result, dimension) => {
      result[dimension] = strongestStatus(findings.filter((finding) => finding.dimension === dimension).map((finding) => finding.status));
      return result;
    },
    { policy: "pass", tone: "pass", language: "pass" } as Record<ReviewDimension, ReviewStatus>,
  );
  const overallStatus = strongestStatus(Object.values(dimensions));
  const dimensionScores = (["policy", "tone", "language"] as ReviewDimension[]).reduce(
    (result, dimension) => {
      result[dimension] = buildDimensionScore(
        dimension,
        findings.filter((finding) => finding.dimension === dimension),
      );
      return result;
    },
    {} as Record<ReviewDimension, DimensionScore>,
  );
  const verdict = verdictFor(overallStatus);
  const checklist = model?.resubmissionChecklist ?? [];
  const actionableChecklist = findings.slice(0, 5).map((finding) => finding.doneWhen);

  return {
    verdict,
    summary: VERDICT_SUMMARIES[verdict],
    dimensions,
    dimensionScores,
    extractedText: model?.extractedText || [input.knownText, input.postCopy].filter(Boolean).join("\n"),
    visualObservations: model?.visualObservations ?? [],
    findings,
    revisedCopy: model?.revisedCopy ?? null,
    resubmissionChecklist: [...new Set([...actionableChecklist, ...checklist])].slice(0, 7),
    engine: model ? "gemini+rules" : "rules-only",
    limitations,
  };
}
import "server-only";

import { GoogleGenAI } from "@google/genai";

import { buildReviewPrompt } from "./prompt";
import { MODEL_REVIEW_JSON_SCHEMA, modelReviewSchema, type ModelReview } from "./schema";
import type { ReviewInput } from "./types";

function parseImageDataUrl(dataUrl: string) {
  const match = dataUrl.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/);
  if (!match) throw new Error("Use a PNG, JPEG, or WebP image.");
  return { mimeType: match[1], data: match[2] };
}

export async function reviewWithGemini(input: ReviewInput): Promise<ModelReview | null> {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey || !input.imageDataUrl) return null;

  const image = parseImageDataUrl(input.imageDataUrl);
  const ai = new GoogleGenAI({ apiKey });
  const response = await ai.models.generateContent({
    model: process.env.GEMINI_MODEL || "gemini-3.5-flash-lite",
    contents: [
      { text: buildReviewPrompt(input) },
      { inlineData: { mimeType: image.mimeType, data: image.data } },
    ],
    config: {
      temperature: 0.1,
      responseMimeType: "application/json",
      responseJsonSchema: MODEL_REVIEW_JSON_SCHEMA,
    },
  });

  if (!response.text) throw new Error("Gemini returned no review output.");
  return modelReviewSchema.parse(JSON.parse(response.text));
}

import type { ReviewDimension, ReviewStatus, Severity } from "./types";

export type ScoringRule = {
  id: string;
  name: string;
  dimension: ReviewDimension;
  status: Exclude<ReviewStatus, "pass">;
  severity: Severity;
  trigger: string;
  action: string;
  sourceBasis: string;
};

const ASCI = "ASCI Code, Chapter I and disclaimer guidance";
const CORPUS = "Minimalist product-page validation (22 pages) and current Meta ad corpus";
const BRAND = "Minimalist About/Values, product pages, and current Meta ad corpus";

export const SCORING_RULES: ScoringRule[] = [
  { id: "P01", name: "Product accuracy", dimension: "policy", status: "block", severity: "critical", trigger: "Product identity, concentration, use, warning, or pack conflicts with the approved record.", action: "Correct the ad or selected product; confirm against the canonical SKU record.", sourceBasis: `${ASCI}; ${CORPUS}; internal product record required` },
  { id: "P02", name: "Objective claim substantiation", dimension: "policy", status: "evidence_required", severity: "high", trigger: "A numeric, percentage, time-bound, clinical, comparative, or measurable efficacy claim appears.", action: "Match the exact wording, population, method, outcome, and timeframe to an approved substantiation record.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "P03", name: "Authority endorsement", dimension: "policy", status: "evidence_required", severity: "high", trigger: "A dermatologist, doctor, expert, lab, or other authority endorsement appears.", action: "Attach the relevant test, survey, permission, approval scope, and date.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "P04", name: "Absolute promise", dimension: "policy", status: "block", severity: "critical", trigger: "The ad promises a cure, guarantee, erasure, elimination, 100% outcome, permanent or inevitable transformation.", action: "Remove the absolute promise and use an approved, calibrated benefit claim; a footnote alone is not enough.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "P05", name: "Product classification", dimension: "policy", status: "human_review", severity: "critical", trigger: "Wording may imply disease treatment, physiological alteration, healing, or a drug-like effect.", action: "Route the exact wording to regulatory/legal against the product classification and approved claim set.", sourceBasis: `Cosmetics Rules, Rule 36; ${CORPUS}` },
  { id: "P06", name: "Result image or testimonial", dimension: "policy", status: "evidence_required", severity: "high", trigger: "A before/after image, consumer result, review, or testimonial appears.", action: "Verify permission, source, timeframe, typicality, alterations, and matching product use.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "P07", name: "Disclaimer adequacy", dimension: "policy", status: "revise", severity: "high", trigger: "A needed disclaimer is absent, unreadable, detached, or contradicts the main claim.", action: "Make the qualification legible and proximate; weaken the main claim when a disclaimer cannot cure it.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "P08", name: "Offer conditions", dimension: "policy", status: "revise", severity: "medium", trigger: "A free item, cashback, discount, or limited-time promotion omits material eligibility or conditions.", action: "Add the threshold, code, dates, exclusions, and a clear proximate route to full terms.", sourceBasis: `ASCI disclaimer guidance; Consumer Protection context; ${CORPUS}` },
  { id: "P09", name: "Missing approved claim", dimension: "policy", status: "evidence_required", severity: "high", trigger: "A factual product claim has no matching approved claim record.", action: "Route the claim to the claims owner; do not infer approval from publication on another surface.", sourceBasis: `${ASCI}; internal claim registry required` },
  { id: "P10", name: "Asset integrity", dimension: "policy", status: "block", severity: "critical", trigger: "The product, packaging, result, or ingredient label appears fabricated or materially altered.", action: "Replace it with an approved asset or obtain explicit review of the alteration.", sourceBasis: `${ASCI}; product-accuracy dependency` },
  { id: "P11", name: "Source-context transfer", dimension: "policy", status: "evidence_required", severity: "high", trigger: "A claim is adapted from a page, pack, testimonial, or study without an approved ad-channel mapping.", action: "Match the ad wording, scope, qualifiers, geography, and channel to an approved claim and evidence record.", sourceBasis: `${ASCI}; ${CORPUS}` },
  { id: "T01", name: "Respect, not shame", dimension: "tone", status: "revise", severity: "high", trigger: "Normal skin or hair is framed as ugly, unacceptable, embarrassing, or the customer's fault.", action: "Name the concern neutrally and preserve the customer's agency.", sourceBasis: BRAND },
  { id: "T02", name: "Inform, not frighten", dimension: "tone", status: "revise", severity: "high", trigger: "The copy escalates danger, anxiety, or urgency beyond the evidence.", action: "State the concern and trade-off proportionately, without fear-based pressure.", sourceBasis: BRAND },
  { id: "T03", name: "Calm confidence", dimension: "tone", status: "revise", severity: "medium", trigger: "Miracle language, transformation theatre, repeated exclamation marks, or emoji pressure dominates.", action: "Replace hype with one specific, direct and supportable benefit.", sourceBasis: BRAND },
  { id: "T04", name: "Transparent expectations", dimension: "tone", status: "revise", severity: "high", trigger: "The copy implies certainty, universality, or instant success.", action: "Use calibrated wording and state material limits, population, and timeframe.", sourceBasis: `${BRAND}; ${ASCI}` },
  { id: "T05", name: "Science as explanation", dimension: "tone", status: "revise", severity: "medium", trigger: "Science or expert language is used as an authority badge without explaining relevance.", action: "Connect the ingredient, formulation, or test to an understandable function and approved benefit.", sourceBasis: BRAND },
  { id: "T06", name: "Promotion without manipulation", dimension: "tone", status: "revise", severity: "medium", trigger: "Artificial scarcity, hidden conditions, or emotional pressure dominates an offer.", action: "Present the offer and its real conditions factually.", sourceBasis: `${BRAND}; ${ASCI}` },
  { id: "L01", name: "Exact product identity", dimension: "language", status: "revise", severity: "high", trigger: "The name or concentration is generic, inconsistent, inferred, or not a registered alias.", action: "Use the canonical product name and concentration from the product record.", sourceBasis: `${CORPUS}; internal SKU record required` },
  { id: "L02", name: "Evidence-matched efficacy verbs", dimension: "language", status: "revise", severity: "high", trigger: "The benefit verb is stronger than its approved evidence or implies transformation.", action: "Use the exact approved verb; where permitted, prefer calibrated language such as helps, supports, or targets.", sourceBasis: `${CORPUS}; ${ASCI}` },
  { id: "L03", name: "Explanatory structure", dimension: "language", status: "revise", severity: "medium", trigger: "Ingredients or science terms appear without an understandable and supportable link to the benefit.", action: "Use ingredient/formulation → relevant function → expected benefit, after policy checks.", sourceBasis: BRAND },
  { id: "L04", name: "Claim completeness", dimension: "language", status: "revise", severity: "high", trigger: "A number or timeframe is detached from its basis, population, qualification, or source marker.", action: "Keep the material basis, population, timeframe, and qualification with the claim.", sourceBasis: `${CORPUS}; ${ASCI}` },
  { id: "L05", name: "Specificity over filler", dimension: "language", status: "revise", severity: "low", trigger: "Generic beauty filler replaces a concrete concern, formulation fact, use, or approved benefit.", action: "Replace the cliché with a specific, supportable product or usage fact.", sourceBasis: BRAND },
  { id: "L06", name: "Scannable hierarchy", dimension: "language", status: "revise", severity: "medium", trigger: "The ad is repetitive, internally inconsistent, or overloaded.", action: "Prioritise product/concern, supporting reason, qualification, then CTA.", sourceBasis: CORPUS },
  { id: "L07", name: "CTA fit", dimension: "language", status: "revise", severity: "medium", trigger: "The CTA promises a result or applies pressure unsupported by the offer.", action: "Use a direct factual action such as Explore product, Shop now, or Build your routine.", sourceBasis: `${CORPUS}; ${BRAND}` },
];

export const RULES_BY_ID = new Map(SCORING_RULES.map((rule) => [rule.id, rule]));

import { SCORING_RULES } from "./rules";
import type { ReviewInput } from "./types";

export function buildReviewPrompt(input: ReviewInput) {
  const rules = SCORING_RULES.map(
    (rule) => `${rule.id} | ${rule.name} | Trigger: ${rule.trigger} | Fix: ${rule.action}`,
  ).join("\n");

  return `You are a cautious first-pass reviewer for Minimalist static ads. Inspect the supplied image and optional context. Return only JSON matching the response schema.

Your job is not to produce a vague score. For every real issue, identify exactly what is off and how to fix it. Separate observed facts from inference. Never invent claim approval, evidence, image provenance, offer terms, or product facts. If a required input is absent, name it. Do not add a finding merely because a product is skincare. Do not create pass findings.

Only use these rule IDs:
${rules}

Review requirements:
- Transcribe all legible visible copy into extractedText.
- Check the creative image, post copy, CTA, disclaimer placement/legibility, product depiction, hierarchy, and tone.
- A product-page claim is not automatically approved for an ad. Flag an objective claim with P09 or P11 when an approved mapping is not provided.
- Use P04 for clear absolutes; P05 for classification uncertainty; P02 for numeric, clinical, time-bound, comparative, or measurable claims.
- Keep each finding atomic and actionable. suggestedReplacement must be null when a safe replacement depends on missing evidence.
- revisedCopy may be null. If supplied, preserve supported product facts and remove or calibrate risky wording.

Input source: ${input.source}
Known visible copy supplied by app: ${input.knownText || "Not supplied"}
Post caption: ${input.postCopy || "Not supplied"}
Product title: ${input.productContext?.title || "Not supplied"}
Product URL: ${input.productContext?.url || "Not supplied"}
Product notes: ${input.productContext?.description || "Not supplied"}`;
}

